import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long a = 0, b = 0;
        double min_ratio = 214748364.0, ratio;

        for (long b_candidate = 1; b_candidate <= n; b_candidate++) {
            long temp_a = (b_candidate * x) / y;
            ratio = Math.abs(b_candidate * x - temp_a * y) / (double)(y * b_candidate);
            if (ratio < min_ratio) {
                a = temp_a;
                b = b_candidate;
                min_ratio = ratio;
            }
            temp_a++;
            ratio = Math.abs(b_candidate * x - temp_a * y) / (double)(y * b_candidate);
            if (ratio < min_ratio) {
                a = temp_a;
                b = b_candidate;
                min_ratio = ratio;
            }
        }

        long limit = (long) Math.sqrt(Math.max(a, b));
        for (long i = 2; i < limit; i++) {
            while (a % i == 0 && b % i == 0) {
                a /= i;
                b /= i;
            }
        }

        System.out.println(a + "/" + b);
        sc.close();
    }
}
